    def __init__(self, client: ScalewayClient) -> None:
        self._client = client

    async def get_domain(
        self,
        *,
        domain_name: str,
        project_id: str,
        region: str | None = None,
    ) -> Domain:
        """
        Retrieve detailed information about a specific domain, including its status, DNS
        configuration, and ownership.

        Args:
            region: The region you want to target
            domain_name: Domain name to get.
            project_id: ID of the Scaleway Project in which to get the domain to create
                the Web Hosting plan.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/webhosting/v1/regions/{region}/domains/{domain_name}",
                region=self._client.region(region),
                domain_name=domain_name,
            ),
            params={"project_id": project_id},
        )
        return Domain.model_validate(data)

    async def check_user_owns_domain(
        self,
        *,
        domain: str,
        region: str | None = None,
        project_id: str | None = None,
    ) -> CheckUserOwnsDomainResponse:
        """
        Check whether you own this domain or not.

        Deprecated by Scaleway.

        Args:
            region: The region you want to target
            domain: Domain for which ownership is to be verified.
            project_id: ID of the project currently in use.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/webhosting/v1/regions/{region}/domains/{domain}/check-ownership",
                region=self._client.region(region),
                domain=domain,
            ),
            body={"project_id": self._client.project_id(project_id)},
        )
        return CheckUserOwnsDomainResponse.model_validate(data)

    async def get_domain_dns_records(
        self,
        *,
        domain: str,
        region: str | None = None,
    ) -> DnsRecords:
        """
        Get DNS records

        Get the set of DNS records of a specified domain associated with a Web Hosting
        plan's domain.

        Args:
            region: The region you want to target
            domain: Domain associated with the DNS records.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/webhosting/v1/regions/{region}/domains/{domain}/dns-records",
                region=self._client.region(region),
                domain=domain,
            ),
        )
        return DnsRecords.model_validate(data)

    async def sync_domain_dns_records(
        self,
        *,
        domain: str,
        region: str | None = None,
        update_web_records: bool | None = None,
        update_mail_records: bool | None = None,
        update_all_records: bool | None = None,
        update_nameservers: bool | None = None,
        custom_records: list[SyncDomainDnsRecordsRequestRecord] | None = None,
        auto_config_domain_dns: AutoConfigDomainDns | None = None,
    ) -> DnsRecords:
        """
        Synchronize your DNS records on the Elements Console and on cPanel.

        Args:
            region: The region you want to target
            domain: Domain for which the DNS records will be synchronized.
            update_web_records: Whether or not to synchronize the web records
                (deprecated, use auto_config_domain_dns).
            update_mail_records: Whether or not to synchronize the mail records
                (deprecated, use auto_config_domain_dns).
            update_all_records: Whether or not to synchronize all types of records. This
                one has priority (deprecated, use auto_config_domain_dns).
            update_nameservers: Whether or not to synchronize domain nameservers
                (deprecated, use auto_config_domain_dns).
            custom_records: Custom records to synchronize.
            auto_config_domain_dns: Whether or not to synchronize each types of records.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/webhosting/v1/regions/{region}/domains/{domain}/sync-domain-dns-records",
                region=self._client.region(region),
                domain=domain,
            ),
            body={
                "update_web_records": update_web_records,
                "update_mail_records": update_mail_records,
                "update_all_records": update_all_records,
                "update_nameservers": update_nameservers,
                "custom_records": custom_records,
                "auto_config_domain_dns": auto_config_domain_dns,
            },
        )
        return DnsRecords.model_validate(data)

    async def search_domains(
        self,
        *,
        domain_name: str,
        project_id: str,
        region: str | None = None,
    ) -> SearchDomainsResponse:
        """
        Search for available domains based on domain name.

        Args:
            region: The region you want to target
            domain_name: Domain name to search.
            project_id: ID of the Scaleway Project in which to search the domain to
                create the Web Hosting plan.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/webhosting/v1/regions/{region}/search-domains",
                region=self._client.region(region),
            ),
            params={"domain_name": domain_name, "project_id": project_id},
        )
        return SearchDomainsResponse.model_validate(data)


